import {normalize,selectTypes,decodeMatrixRows,selectMatrixRows,matrixDate,matrixFacets,matrixPage,matrixStates,stateLabels,stateColors} from './protocol-model.mjs';
const cache=new Map(),KEY='atlas-protocol-matrix-view-v1';let catalogRequest;
async function readJSON(file){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(file,{signal:controller.signal});if(!response.ok)throw Error('No se pudo cargar la matriz. Revisa la conexión o guarda su paquete offline.');return await response.json();}catch(error){if(error.name==='AbortError')throw Error('La carga está tardando. Reintenta con conexión o usa la copia offline.');if(error instanceof TypeError||error instanceof SyntaxError)throw Error('No se pudo leer el detalle de protocolos. Revisa la conexión o guarda la matriz para usarla offline.');throw error;}finally{clearTimeout(timer);}}
function loadCatalog(){return catalogRequest||=readJSON('protocols/catalog.json').then(catalog=>{if(catalog.schema!==1||!Array.isArray(catalog.types)||catalog.types.length!==catalog.totalTypes)throw Error('Versión de catálogo no compatible.');return catalog;}).catch(error=>{catalogRequest=null;throw error;});}
function loadType(catalog,type){const key=catalog.source.sha256+':'+type.id;if(cache.has(key)){const value=cache.get(key);cache.delete(key);cache.set(key,value);return value;}const pending=readJSON('protocols/'+type.file).then(chunk=>decodeMatrixRows(chunk,catalog,type)).catch(error=>{if(cache.get(key)===pending)cache.delete(key);throw error;});cache.set(key,pending);if(cache.size>8)cache.delete(cache.keys().next().value);return pending;}
export async function renderProtocolCatalog(root,ctx){
 const esc=ctx.esc,number=n=>Number(n).toLocaleString('es-CL');root.innerHTML='<p role="status">Cargando catálogo de protocolos…</p>';
 let catalog;
 try{catalog=await loadCatalog();}catch(error){if(!root.isConnected)return;root.innerHTML=`<p role="alert">${esc(error.message)}</p><button id="retryProtocolCatalog">Reintentar</button>`;root.querySelector('#retryProtocolCatalog').onclick=()=>renderProtocolCatalog(root,ctx);return;}
 if(!root.isConnected)return;
 let chosen=null,rows=[],page=0,serial=0,recordId=null,stored={};const filters={state:'',level:'',receiver:'',query:''};
 try{const value=JSON.parse(localStorage.getItem(KEY)||'null');if(value?.sourceSha256===catalog.source.sha256)stored=value;}catch{}
 const date=value=>{const iso=matrixDate(value,catalog.source.date1904);return iso&&/^\d{4}-\d{2}-\d{2}$/.test(iso)?iso.split('-').reverse().join('-'):iso||'Sin fecha documentada';};
 root.innerHTML=`<section class="matrixIntro"><div><span class="section-label">MATRIZ DE CONTROL · REV1</span><h2>Seleccionar protocolo</h2><p>${number(catalog.totalRecords)} registros · ${number(catalog.totalTypes)} códigos · corte ${esc(catalog.source.cutoff.split('-').reverse().join('-'))}</p><small class="matrixScope">Matriz completa · todos los niveles del Excel</small></div><a href="source/${esc(catalog.source.filename)}" download="${esc(catalog.source.originalName)}" class="sourceLink">Descargar Excel original</a></section><div class="matrixOverview">${matrixStates.map(state=>`<div><i style="background:${stateColors[state]}"></i><span>${stateLabels[state]}</span><b>${number(catalog.audit.calculatedStates[state]||0)}</b></div>`).join('')}</div>${Object.keys(catalog.audit.differences).length?'<p class="matrixReconcile">Recuento por filas del registro; hay una diferencia respecto del resumen del Excel. <button id="matrixAuditOpen">Ver comprobación</button></p>':''}<div class="matrixLayout"><section class="matrixPicker"><div class="matrixPickerControls"><label for="matrixSpecialty">Especialidad / actividad</label><select id="matrixSpecialty"><option value="">Todas las especialidades</option>${catalog.specialties.map(group=>`<option value="${group.id}">${esc(group.name)} · ${number(group.count)}</option>`).join('')}</select><label for="matrixTypeSearch">Buscar protocolo</label><input id="matrixTypeSearch" type="search" placeholder="Pintura asepsia baja, planchas RH, código…" autocomplete="off"><label for="matrixType">Protocolo / proceso</label><select id="matrixType"><option value="">Selecciona un protocolo</option></select><p id="matrixTypeCount" role="status"></p></div><details class="matrixBrowse"><summary>Explorar protocolos por especialidad</summary><div id="matrixGroups"></div></details></section><section id="matrixRegisters" class="matrixRegisters" aria-label="Registros del protocolo"><div class="matrixPlaceholder"><h3>Elige un protocolo</h3><p>Despliega una especialidad o busca por nombre o código. Después podrás consultar sus folios, niveles, estados y responsables.</p></div></section></div><details class="matrixSource"><summary>Fuente y comprobación de la matriz</summary><p>${esc(catalog.source.originalName)} · ${esc(catalog.source.registrySheet)} · ${esc(catalog.source.revision)}</p><p>La consulta conserva los valores guardados en el archivo. Los estados de esta matriz no equivalen a la aprobación técnica de los registros locales de Atlas.</p><p>${catalog.audit.statusWhitespace.length} estados contienen espacios adicionales: se muestran como «Abierto». El recuento por filas da ${number(catalog.audit.calculatedStates.ABIERTO)} abiertos; el resumen del Excel muestra ${number(catalog.audit.declaredStates.ABIERTO)}. El original se conserva íntegro.</p><p>${catalog.audit.duplicateFolios.length} combinaciones de código y folio se repiten; se mantienen todas las filas. Las tablas dinámicas y hojas históricas ocultas no se suman de nuevo.</p><p>«RECINTOS» y «NIVEL» se muestran tal como figuran en el Excel; no se asignan automáticamente a las geometrías del visor.</p><small>SHA256 ${esc(catalog.source.sha256)}</small></details>`;
 const $=id=>root.querySelector('#'+id),save=()=>{try{localStorage.setItem(KEY,JSON.stringify({sourceSha256:catalog.source.sha256,specialty:$('matrixSpecialty').value,query:$('matrixTypeSearch').value,typeId:chosen?.id||'',filters,page,recordId}));}catch{}};
 if($('matrixAuditOpen'))$('matrixAuditOpen').onclick=()=>{root.querySelector('.matrixSource').open=true;root.querySelector('.matrixSource').scrollIntoView({block:'start'});};
 $('matrixSpecialty').value=catalog.specialties.some(g=>g.id===stored.specialty)?stored.specialty:'';$('matrixTypeSearch').value=typeof stored.query==='string'?stored.query.slice(0,300):'';
 function types(){return selectTypes(catalog,{specialty:$('matrixSpecialty').value,query:$('matrixTypeSearch').value});}
 function groups(){const available=types(),ids=new Set(available.map(type=>type.id));$('matrixType').innerHTML='<option value="">Selecciona un protocolo</option>'+available.map(type=>`<option value="${type.id}">${esc(type.code+' · '+type.name)}</option>`).join('');$('matrixType').value=chosen&&ids.has(chosen.id)?chosen.id:'';$('matrixTypeCount').textContent=number(available.length)+(available.length===1?' protocolo disponible':' protocolos disponibles');$('matrixGroups').innerHTML=catalog.specialties.filter(group=>(!$('matrixSpecialty').value||group.id===$('matrixSpecialty').value)&&group.typeIds.some(id=>ids.has(id))).map(group=>{const matches=available.filter(type=>group.typeIds.includes(type.id));return `<details class="matrixGroup" ${$('matrixSpecialty').value||$('matrixTypeSearch').value||chosen&&group.typeIds.includes(chosen.id)?'open':''}><summary><span>${esc(group.name)}</span><small>${matches.length} protocolos</small></summary><div>${matches.map(type=>`<button class="matrixTypeChoice" data-matrix-type="${type.id}" aria-pressed="${chosen?.id===type.id}"><span>${esc(type.name)}</span><small>${esc(type.code)} · ${number(type.count)} registros</small></button>`).join('')}</div></details>`;}).join('')||'<p class="matrixNoResults">Sin protocolos coincidentes. Prueba otro nombre o código.</p>';root.querySelectorAll('[data-matrix-type]').forEach(button=>button.onclick=()=>choose(button.dataset.matrixType));}
 async function choose(id,restore=false){const type=types().find(type=>type.id===id);const request=++serial;chosen=type||null;rows=[];recordId=null;page=0;if(!restore)Object.assign(filters,{state:'',level:'',receiver:'',query:''});groups();save();if(!type){$('matrixRegisters').innerHTML='<div class="matrixPlaceholder"><h3>Elige un protocolo</h3><p>Selecciona un proceso para consultar sus registros.</p></div>';return;}$('matrixRegisters').innerHTML=`<p role="status">Cargando ${esc(type.name)}…</p>`;try{const loaded=await loadType(catalog,type);if(request!==serial||!root.isConnected)return;rows=loaded;if(restore){for(const key of ['state','level','receiver','query'])if(typeof stored.filters?.[key]==='string')filters[key]=stored.filters[key].slice(0,500);page=Number.isInteger(stored.page)?stored.page:0;recordId=typeof stored.recordId==='string'?stored.recordId:null;}registerShell();save();if(innerWidth<700)$('matrixRegisters').scrollIntoView({block:'start'});}catch(error){if(request!==serial||!root.isConnected)return;$('matrixRegisters').innerHTML=`<h3>${esc(type.name)}</h3><p role="alert">${esc(error.message)}</p><button id="retryMatrixType">Reintentar detalle</button>`;$('retryMatrixType').onclick=()=>choose(type.id,restore);}}
 const optionList=(field,empty)=>matrixFacets(rows,field).map(([value,n])=>`<option value="${esc(value||'~')}">${esc(field==='state'?stateLabels[value]||value||empty:value||empty)} · ${number(n)}</option>`).join('');
 function registerShell(){const fieldLabels=catalog.source.columns; $('matrixRegisters').innerHTML=`<div class="matrixTypeHeading"><span class="section-label">${esc(chosen.code)}</span><h3>${esc(chosen.name)}</h3><p>${number(chosen.count)} registros en la matriz${chosen.names.length>1?' · '+chosen.names.length+' variantes de nombre en origen':''}</p><button id="changeMatrixType">Cambiar protocolo</button></div><div class="matrixRecordFilters"><label>Estado<select id="matrixState"><option value="">Todos los estados</option>${optionList('state','Sin estado documentado')}</select></label><label>Nivel del Excel<select id="matrixLevel"><option value="">Todos los niveles</option>${optionList('level','Sin nivel documentado')}</select></label><label>Recibe<select id="matrixReceiver"><option value="">Todas las personas</option>${optionList('receiver','Sin receptor documentado')}</select></label><label class="matrixRecordSearch">Buscar en los registros<input id="matrixRecordSearch" type="search" placeholder="Folio, elemento, ejes o persona…"></label></div><div class="matrixResultHead"><strong id="matrixResultCount" role="status"></strong><button id="clearMatrixFilters">Limpiar filtros</button></div><div class="matrixTableWrap"><table class="matrixTable"><thead><tr><th>Folio</th><th>Nivel</th><th class="matrixWide">Elemento / ejes</th><th>Estado</th><th class="matrixWide">Recibe</th></tr></thead><tbody id="matrixRows"></tbody></table></div><div class="matrixPagination"><button id="matrixPrevious">Anterior</button><span id="matrixPage"></span><button id="matrixNext">Siguiente</button></div>`;
  $('changeMatrixType').onclick=()=>{$('matrixType').scrollIntoView({block:'nearest'});$('matrixType').focus({preventScroll:true});};for(const [id,key] of [['matrixState','state'],['matrixLevel','level'],['matrixReceiver','receiver']]){if(![...$(id).options].some(option=>option.value===filters[key]))filters[key]='';$(id).value=filters[key];$(id).onchange=event=>{filters[key]=event.target.value;page=0;recordId=null;renderRows();};}$('matrixRecordSearch').value=filters.query;$('matrixRecordSearch').oninput=event=>{filters.query=event.target.value;page=0;recordId=null;renderRows();};$('clearMatrixFilters').onclick=()=>{Object.assign(filters,{state:'',level:'',receiver:'',query:''});page=0;recordId=null;registerShell();};$('matrixPrevious').onclick=()=>{page--;recordId=null;renderRows();};$('matrixNext').onclick=()=>{page++;recordId=null;renderRows();};renderRows();
 }
 function renderRows(){const matches=selectMatrixRows(rows,filters),current=matrixPage(matches,page);page=current.page;$('matrixResultCount').textContent=number(matches.length)+' de '+number(rows.length)+' registros';$('matrixRows').innerHTML=current.rows.map(record=>`<tr data-matrix-id="${esc(record.id)}" class="${recordId===record.id?'selected':''}"><td><button data-matrix-row="${esc(record.id)}" aria-expanded="${recordId===record.id}">${esc(record.folio||'Sin folio')}</button><small>Fila ${record.sourceRow}</small></td><td>${esc(record.level||'Sin nivel')}</td><td class="matrixWide">${esc(record.element||'Sin elemento')}<small>${esc(record.axes||'Sin ejes')}</small></td><td><span class="matrixState" style="--state-color:${stateColors[record.state?.trim()]||'#8a929b'}">${esc(stateLabels[record.state?.trim()]||record.state||'Sin estado')}</span></td><td class="matrixWide">${esc(record.receiver||'Sin receptor')}</td></tr>`).join('')||'<tr><td colspan="5">Sin registros coincidentes.</td></tr>';$('matrixPage').textContent='Página '+(page+1)+' de '+current.pages;$('matrixPrevious').disabled=page===0;$('matrixNext').disabled=page+1>=current.pages;root.querySelectorAll('[data-matrix-row]').forEach(button=>button.onclick=()=>{const id=button.dataset.matrixRow;recordId=recordId===id?null:id;renderRows();[...root.querySelectorAll('[data-matrix-row]')].find(node=>node.dataset.matrixRow===id)?.focus({preventScroll:true});});const record=current.rows.find(row=>row.id===recordId);if(record){const duplicate=catalog.audit.duplicateFolios.find(group=>group.code===chosen.code&&group.rows.includes(record.sourceRow));const detail=`<h4>${esc(chosen.code)} · Folio ${esc(record.folio||'Sin folio')}</h4><dl>${Object.entries(catalog.source.columns).map(([field,name])=>`<div><dt>${esc(name)}</dt><dd>${esc(['issued','closedDate'].includes(field)?date(record[field]):record[field]??'Sin dato documentado')}</dd></div>`).join('')}</dl><p class="matrixRecordSource">${esc(catalog.source.registrySheet)} · fila ${record.sourceRow}. Valores originales guardados; consulta de solo lectura.</p>${duplicate?`<p>Este código y folio también aparece en las filas ${duplicate.rows.join(', ')}. Las filas se conservan por separado.</p>`:''}`;root.querySelector('[data-matrix-id="'+record.id+'"]').insertAdjacentHTML('afterend','<tr class="matrixExpandedRow"><td colspan="5"><section id="matrixRecordDetail" class="matrixRecordDetail" aria-label="Ficha del protocolo">'+detail+'</section></td></tr>');}save();}
 function selectionChanged(){const allowed=types();if(chosen&&!allowed.some(type=>type.id===chosen.id))choose('');else{groups();save();}}
 $('matrixSpecialty').onchange=selectionChanged;$('matrixTypeSearch').oninput=selectionChanged;$('matrixType').onchange=event=>choose(event.target.value);groups();if(types().some(type=>type.id===stored.typeId))choose(stored.typeId,true);
}
